//! Cargo-driven `iphlpapi.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is iphlpapi-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7be90000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffae000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffae000000u64)),
        o => panic!("iphlpapi-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "import:dhcpcsvc", "import:advapi32", "import:psapi", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:crate:tdilib-rust::TRUE", "engine:oldnames"],
        "x86_64" => &["body", "engine:wine", "import:dhcpcsvc", "import:advapi32", "import:psapi", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:crate:tdilib-rust::TRUE", "engine:oldnames"],
        "aarch64" => &["body", "engine:wine", "import:dhcpcsvc", "import:advapi32", "import:psapi", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:crate:tdilib-rust::TRUE", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/iphlpapi",
        "dll/win32/iphlpapi",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/wine",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "GetAdaptersAddressesV2",
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_CRT_NO_POSIX_ERROR_CODES",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("iphlpapi-rust")
        .rc("dll/win32/iphlpapi/iphlpapi.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll")
        .spec_stubs()
        .import_lib("base/services/dhcpcsvc/dhcpcsvc.spec", "dhcpcsvc.dll", "dhcpcsvc")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/psapi/psapi.spec", "psapi.dll", "psapi")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
